 v={'teaching_audio':'E5/N2/M1','teaching_captions':'C5/N2/11:40','lesson_export':'E5N2C5','access_review':'E5N2C5','sponsor_audio':sponsor,'sponsor_captions':'SC5/60seconds','sponsor_export':'S4/60/00:55','sponsor_copy':'S4-held','old_download':'S3-revoked','public_copy':'E5N2C5','sponsor_card':'S4-held','sponsor_sidecar':'S4-held/SC5'}
 req={'teacher':'E5/N2/C5/full','reviewer':'E5N2C5/inspect-after-upload','sponsor':sponsor+'/60/00:55','reader-sol':'C5/full_lesson'}
 asks={'teacher':'Can you keep the full E5 lesson with N2 and retimed C5, including the tool setting?|可保留完整E5配N2和重定时C5，含工具设置吗？','reviewer':'Please reserve a check of final E5N2C5 after I upload it; approve only that snapshot.|请预约上传后核E5N2C5，只审核这份快照。','sponsor':('Can we deliver the 60-second N2 narration/M0 cut with the full 00:55 step?' if branch=='A' else 'Can we use our owned silent V0/M0 with captions for the 60-second cut, keeping00:55 complete?')+'|'+('可交N2旁白加M0的一分钟短片、完整保留00:55步骤吗？' if branch=='A' else '一分钟短片用自有无声V0/M0加字幕、保留完整00:55步骤，可以吗？'),'reader-sol':'Will the full lesson with retimed C5 meet the caption issue you raised? I will send the actual link after replacement.|完整课配重定时C5能解决你提的字幕问题吗？替换后发实际链接。'}
 deliveries=[('transcript','Plug the board into the marked port. The green light means it is ready. Turn the dial to the first mark. Pause here to compare both outputs. Keep the cover beside the board while you check. That is the full setup; the final minute shows the tool setting again.|把板接到标记端口。绿灯表示就绪。旋钮转到第一格。在这里暂停，对比两种输出。检查时把盖子放在板旁。这就是完整设置，最后一分钟会再演示工具设置。'),('sponsor','S4 is now in your workspace, including 00:55. The S3 download is revoked and the scheduled card points to S4.|S4已经放进你们工作区，00:55那步也在。旧S3下载关了，预约卡也改到S4。'),('reader-sol','The full lesson has captions timed to the new narration in reviewed E5N2C5. That version is now in the public release queue.|完整课的字幕已经跟新旁白对齐，用的是审核过的E5N2C5。新版现已排进公开发布队列。'),('teacher','E5N2C5 is reviewed and attached to the public queue. The sponsor copy preserves the contracted product step with its separately cleared audio.|E5N2C5审核好了，已经排进公开发布。整节课和工具设置近景都保留，赞助短片也按自己的音频许可另做了。'),('main','The updated electronics lesson has captions timed to the new narration. It is queued for release with the full demonstration and transcript.|电子制作课的字幕已跟新旁白对齐，新版正在等预约发布，完整演示和文字稿都会保留。'),('old-answer','The caption timings are fixed for the lesson. The sponsor cut has its own captions and audio license; I replaced that held copy too.|教程字幕时间已修好，赞助短片的字幕和音频许可另算，那份已交副本也替换了。')]
